import {destinations,categories,heroImage} from './data.js';
import {attachCredits} from './credits.js';
const $ = (s) => document.querySelector(s);
const esc = (v='') => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = v => {try {const u=new URL(v);return u.protocol==='https:'?u.href:'';}catch{return '';}};
const KEY='tripwise.fieldnotes.v1', CACHE='tripwise.places.v1';
let storageWarning=false;
function read(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
function freshTrip(){return {name:'My next adventure',start:'',days:3,items:[]};}
function restoreTrip(){const v=read(KEY);if(!v||typeof v!=='object')return freshTrip();return {name:typeof v.name==='string'?v.name.slice(0,80):'My next adventure',start:/^\d{4}-\d{2}-\d{2}$/.test(v.start||'')?v.start:'',days:Math.max(1,Math.min(14,Number(v.days)||3)),items:Array.isArray(v.items)?v.items.filter((x,i,a)=>x&&destinations.some(d=>d.id===x.id)&&a.findIndex(y=>y?.id===x.id)===i).map(x=>({id:x.id,day:Math.max(1,Math.min(14,Number(x.day)||1)),note:typeof x.note==='string'?x.note.slice(0,500):''})):[]};}
let trip=restoreTrip(); trip.days=Math.max(trip.days,...trip.items.map(i=>i.day));
let state={places:[],loading:true,error:'',cached:false,query:'',category:'All places',region:'All regions',sort:'editorial',view:location.hash==='#trip'?'trip':'explore'};
let toastTimer,activeDetail=null,loadSequence=0;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(trip));storageWarning=false;}catch{storageWarning=true;toast('Browser storage is unavailable. Export your trip to keep a copy.');}updateCount();}
function updateCount(){$('#trip-count').textContent=trip.items.length;}
function imageMarkup(d,extra=''){return d.image?`<img src="${esc(safeUrl(d.image))}" alt="${esc(d.name)}" loading="lazy" ${extra}>`:`<div class="empty-icon" style="display:grid;place-items:center;height:100%" aria-label="No photograph available">↗</div>`;}
function photoCreditMarkup(d){const c=d.photoCredit;if(!d.image||!c)return '';return `<div class="photo-credit">Photo: <a href="${esc(safeUrl(c.source)||d.source)}" target="_blank" rel="noopener">${esc(c.artist||'Public domain')}</a> · <a href="${esc(safeUrl(c.licenseUrl)||safeUrl(c.source)||d.source)}" target="_blank" rel="noopener">${esc(c.license)}</a> · cropped</div>`;}
function findPlace(id){return state.places.find(p=>p.id===id)||destinations.find(p=>p.id===id);}
function isSaved(id){return trip.items.some(i=>i.id===id);}
function addPlace(id){if(!destinations.some(d=>d.id===id))return toast('Please choose a valid destination.');if(isSaved(id))return toast('This place is already in your trip.');trip.items.push({id,day:1,note:''});persist();toast(`${findPlace(id).name} added to your trip`);if(state.view==='trip')renderTrip();else renderCards();if(activeDetail)renderDetail(activeDetail);}
async function loadPlaces(){const sequence=++loadSequence;state.loading=true;state.error='';state.cached=false;render();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);
  try{
    const params=new URLSearchParams({action:'query',format:'json',origin:'*',redirects:'1',prop:'extracts|pageimages|coordinates',exintro:'1',explaintext:'1',piprop:'thumbnail|name',pithumbsize:'900',titles:destinations.map(d=>d.id.replaceAll('_',' ')).join('|')});
    const response=await fetch(`https://en.wikipedia.org/w/api.php?${params}`,{signal:controller.signal});
    if(!response.ok)throw new Error(`The places service returned ${response.status}.`);
    const result=await response.json();if(result.error||!result.query?.pages)throw new Error('The places service returned an unexpected response.');
    const pages=Object.values(result.query.pages);const redirect=new Map((result.query.redirects||[]).map(r=>[r.from,r.to]));
    let places=destinations.map(d=>{const title=d.id.replaceAll('_',' ');const page=pages.find(p=>p.title===(redirect.get(title)||title));if(!page?.extract||page.missing!==undefined)return null;return {...d,description:page.extract,image:safeUrl(page.thumbnail?.source),coordinates:page.coordinates?.[0]||null,source:`https://en.wikipedia.org/wiki/${encodeURIComponent(page.title.replaceAll(' ','_'))}`,imageName:page.pageimage||''};}).filter(Boolean);
    if(!places.length)throw new Error('No destination information was returned.');
    places=await attachCredits(places,controller.signal);
    if(sequence!==loadSequence)return;state.places=places;
    try{localStorage.setItem(CACHE,JSON.stringify({savedAt:Date.now(),places}));}catch{}
}catch(error){if(sequence!==loadSequence)return;const cached=read(CACHE);const places=cached?.places?.filter?.(p=>p&&destinations.some(d=>d.id===p.id)&&typeof p.description==='string');if(places?.length){state.places=places.map(p=>p.photoCredit?p:{...p,image:''});state.cached=true;state.error='The live service is unavailable. Showing previously loaded places.';}else{state.places=[];state.error=error.name==='AbortError'?'The places service took too long to respond. Please try again.':'We couldn’t load destinations. Check your connection and try again.';}}
  finally{clearTimeout(timeout);if(sequence===loadSequence){state.loading=false;render();}}
}
function filteredPlaces(){let list=state.places.filter(p=>(state.category==='All places'||p.category===state.category)&&(state.region==='All regions'||p.region===state.region)&&`${p.name} ${p.country} ${p.category} ${p.tag}`.toLowerCase().includes(state.query.trim().toLowerCase()));if(state.sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));if(state.sort==='za')list.sort((a,b)=>b.name.localeCompare(a.name));if(state.sort==='short')list.sort((a,b)=>a.days-b.days);return list;}
function hero(){return `<section class="hero"><div><div class="eyebrow">For the wonderfully curious</div><h1>Go somewhere<br>that <em>stays with you.</em></h1><p>Quiet corners. Unexpected turns. Places that feel like you.<br>Find your next escape, one little discovery at a time.</p><div class="hero-actions"><a class="button" href="#discover" id="start-exploring">Find my next chapter <span aria-hidden="true">↗</span></a><span class="little-note">Your someday starts here.</span></div></div><div class="hero-art"><div class="hero-photo"><img src="${heroImage}" alt="A Balinese temple beside a lake in Bali" fetchpriority="high"><div class="photo-caption"><small>POSTCARD NO. 001 · INDONESIA</small><p>A slower kind of somewhere.</p></div></div><div class="stamp"><span>TAKE THE</span><b>↗</b><span>SCENIC ROUTE</span></div><div class="ticket"><span class="ticket-icon" aria-hidden="true">✳</span><div><small>LESS PLANNING. MORE POSSIBILITY.</small><strong>A world of your own.</strong></div></div></div></section>`;}
function render(){updateCount();document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.view);a.toggleAttribute('aria-current',a.dataset.nav===state.view);if(a.dataset.nav===state.view)a.setAttribute('aria-current','page');});if(state.view==='trip')return renderTrip();
  $('#main').innerHTML=`${hero()}<section id="discover" aria-labelledby="discover-title"><div class="section-head"><div><h2 id="discover-title">Follow your kind of feeling.</h2><p>A few good places to get beautifully lost.</p></div><span class="live">${state.loading?'Finding your next escape':state.cached?'Saved destination information':'Live destination information'}</span></div><div class="toolbar"><div class="searchbox"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="Search destinations" placeholder="Try Kyoto, India, or a little adventure…" value="${esc(state.query)}" maxlength="100"></div><select id="region" aria-label="Filter by region">${['All regions','Asia','Europe','Africa','Americas'].map(v=>`<option${state.region===v?' selected':''}>${v}</option>`).join('')}</select><select id="sort" aria-label="Sort destinations">${[['editorial','Our little shortlist'],['az','Name: A to Z'],['za','Name: Z to A'],['short','Shortest escape first']].map(([v,t])=>`<option value="${v}"${state.sort===v?' selected':''}>${t}</option>`).join('')}</select></div><div class="filters" role="group" aria-label="Filter by travel style">${categories.map((c,i)=>`<button class="chip${state.category===c?' active':''}" aria-pressed="${state.category===c}" data-category="${esc(c)}">${['✳','♧','⌂','≈','↗','▦','☼'][i]} &nbsp;${c}</button>`).join('')}</div><div id="load-message"></div><div class="results-line"><span id="result-count" role="status"></span><button class="text-button" id="reset-filters">Reset filters</button></div><div class="grid" id="cards" aria-busy="${state.loading}"></div></section><aside class="callout"><div><span class="orb" aria-hidden="true">↗</span><div><h3>A good trip starts with a little collection.</h3><p>Save the places that speak to you. We’ll keep them together.</p></div></div><a class="button outline" href="#trip">Open my trip <span aria-hidden="true">→</span></a></aside>`;
  $('#search').addEventListener('input',e=>{state.query=e.target.value;renderCards();});$('#region').addEventListener('change',e=>{state.region=e.target.value;renderCards();});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;renderCards();});
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',String(c===b));});renderCards();}));$('#reset-filters').onclick=resetFilters;$('#start-exploring').onclick=e=>{e.preventDefault();$('#discover').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#search').focus({preventScroll:true});};renderCards();
}
function resetFilters(){state.query='';state.category='All places';state.region='All regions';state.sort='editorial';render();$('#search').focus();}
function renderCards(){if(state.view!=='explore'||!$('#cards'))return;$('#result-count').textContent=state.loading?'Good things are on their way…':`${filteredPlaces().length} places, endless possibilities`;$('#load-message').innerHTML=state.error?`<div class="banner" role="alert"><span>${esc(state.error)}</span><button class="text-button" id="retry">Try again</button></div>`:'';if($('#retry'))$('#retry').onclick=loadPlaces;
  if(state.loading){$('#cards').innerHTML=Array.from({length:6},()=>'<div class="skeleton" aria-hidden="true"></div>').join('');return;}
  const list=filteredPlaces();$('#cards').innerHTML=list.length?list.map(d=>`<article class="card"><div class="card-image"><button class="image-button" data-detail="${esc(d.id)}" aria-label="Explore ${esc(d.name)}">${imageMarkup(d)}</button><span class="card-category">${esc(d.category)}</span><button class="save-button${isSaved(d.id)?' saved':''}" data-save="${esc(d.id)}" aria-label="${isSaved(d.id)?'Saved:':'Add to trip:'} ${esc(d.name)}" aria-pressed="${isSaved(d.id)}">${isSaved(d.id)?'✓':'+'}</button></div><div class="card-body">${photoCreditMarkup(d)}<div class="location">${esc(d.country)} <span aria-hidden="true">·</span> ${esc(d.region)}</div><h3><button class="title-button" data-detail="${esc(d.id)}">${esc(d.name)}</button></h3><p>${esc(d.description)}</p><div class="card-bottom"><span>${d.days}-day escape <span aria-hidden="true">·</span> ${esc(d.category)}</span><button data-detail="${esc(d.id)}">Take a look ↗</button></div></div></article>`).join(''):`<div class="empty"><div class="empty-icon" aria-hidden="true">⌕</div><h3>${state.error?'A small detour.':'Nothing here. Yet.'}</h3><p>${state.error?'The destination service couldn’t be reached. Your saved trip is still available.':'Try another place, a wider region, or a different kind of feeling.'}</p><button class="button" id="empty-action">${state.error?'Retry loading places':'Clear filters'}</button></div>`;
  if($('#empty-action'))$('#empty-action').onclick=state.error?loadPlaces:resetFilters;bindPlaceActions($('#cards'));bindImageErrors($('#cards'));
}
function bindImageErrors(root){root.querySelectorAll('img').forEach(img=>{img.addEventListener('error',()=>{const fallback=document.createElement('span');fallback.className='empty-icon';fallback.style.cssText='display:grid;place-items:center;height:100%';fallback.textContent='↗';fallback.setAttribute('aria-label','Photograph unavailable');img.replaceWith(fallback);},{once:true});});}
function bindPlaceActions(root){root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetails(b.dataset.detail));root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{if(isSaved(b.dataset.save))toast('Already collected. Manage this place in My Trip.');else addPlace(b.dataset.save);});}
function openDetails(id){const d=findPlace(id);if(!d)return toast('That destination is unavailable.');activeDetail=id;renderDetail(id);$('#details').showModal();document.body.classList.add('modal-open');}
function renderDetail(id){const d=findPlace(id);$('#details').innerHTML=`<div class="details-top">${imageMarkup(d)}<button class="close" aria-label="Close destination details">×</button></div><div class="detail-body"><div class="location">${esc(d.country)} · ${esc(d.category)}</div><h2 id="detail-title">${esc(d.name)}</h2><div class="little-note">${esc(d.tag)}</div><p>${esc(d.description||'Live destination information is unavailable right now. Retry loading places from Explore.')}</p><div class="detail-facts"><div><span>Make time for</span><b>${d.days} days, at your pace</b></div><div><span>In this corner</span><b>${esc(d.region)}</b></div><div><span>Your feeling</span><b>${esc(d.category)}</b></div></div><div class="detail-bottom"><a class="source-link" href="${esc(d.source||`https://en.wikipedia.org/wiki/${encodeURIComponent(d.id)}`)}" target="_blank" rel="noopener">Read the full story ↗</a><button class="button orange" id="detail-save"${isSaved(id)?' disabled':''}>${isSaved(id)?'✓ In your trip':'Collect this place +'}</button></div><div class="detail-links">${d.coordinates?`<a class="source-link" href="https://www.openstreetmap.org/?mlat=${Number(d.coordinates.lat)}&mlon=${Number(d.coordinates.lon)}#map=12/${Number(d.coordinates.lat)}/${Number(d.coordinates.lon)}" target="_blank" rel="noopener">Find on map ↗</a>`:''}${d.imageName?`<a class="source-link" href="https://en.wikipedia.org/wiki/File:${encodeURIComponent(d.imageName)}" target="_blank" rel="noopener">Photo credit & license ↗</a>`:''}</div>${photoCreditMarkup(d)}<p class="credit">Destination text from Wikipedia, CC BY-SA. Suggested visit lengths and travel styles are editorial guidance, not live booking information.</p></div>`;$('#details .close').onclick=()=>$('#details').close();$('#detail-save').onclick=()=>addPlace(id);bindImageErrors($('#details'));}
function tripDate(day){if(!trip.start)return '';const date=new Date(`${trip.start}T12:00:00`);date.setDate(date.getDate()+day-1);return date.toLocaleDateString('en',{month:'short',day:'numeric'});}
function renderTrip(){const countries=new Set(trip.items.map(i=>findPlace(i.id)?.country));$('#main').innerHTML=`<section class="trip-header"><div><div class="eyebrow">Your personal field notes</div><h1>A little plan. <em>A big possibility.</em></h1><p>All the places you’ve collected, ready for their next chapter.</p></div><div class="trip-actions"><a class="button outline small" href="#explore">＋ Find more places</a><button class="button small" id="export"${trip.items.length?'':' disabled'}>Export trip ↓</button><button class="button outline small" id="print"${trip.items.length?'':' disabled'}>Print / PDF</button></div></section>${storageWarning?'<div class="banner" role="alert">Browser storage is unavailable. Export your itinerary to keep a copy.</div>':''}<div class="trip-layout"><section aria-label="Itinerary"><div class="trip-settings"><div class="field"><label for="trip-name">Name your chapter</label><input id="trip-name" maxlength="80" value="${esc(trip.name)}"></div><div class="field"><label for="trip-start">First day (optional)</label><input type="date" id="trip-start" value="${esc(trip.start)}"></div><div class="field" style="flex:0 0 75px"><label for="trip-days">Days</label><select id="trip-days">${Array.from({length:14},(_,i)=>`<option value="${i+1}"${trip.days===i+1?' selected':''}>${i+1}</option>`).join('')}</select></div></div>${trip.items.length?Array.from({length:trip.days},(_,i)=>i+1).map(day=>`<section><div class="day-head"><b>Day ${String(day).padStart(2,'0')}</b><span>${tripDate(day)}</span></div>${trip.items.filter(x=>x.day===day).map(item=>tripItem(item)).join('')||'<p style="color:var(--muted);font-size:12px;padding:10px 0 20px">Leave a little room for serendipity. Assign a saved place to this day.</p>'}</section>`).join(''):`<div class="empty"><div class="empty-icon" aria-hidden="true">↗</div><h3>Your story is still unwritten.</h3><p>A mountain morning? A city you’ve never met? Start collecting a few places and build a trip that feels like you.</p><a href="#explore" class="button">Find your first place ↗</a></div>`}</section><aside class="route-card"><div class="eyebrow">THE JOURNEY SO FAR</div><h2 id="summary-name">${esc(trip.name||'My next adventure')}</h2><p>A collection of possibilities.<br>One adventure that’s entirely yours.</p><div class="route-sketch" aria-hidden="true"><svg viewBox="0 0 240 150"><path d="M18 110 C45 150 30 20 95 35 S130 145 174 90 S190 20 226 38" fill="none" stroke="#e1b692" stroke-width="1.5" stroke-dasharray="5 6"/><circle cx="18" cy="110" r="6" fill="#e1b692"/><circle cx="95" cy="35" r="5" fill="#f5f3eb"/><circle cx="174" cy="90" r="5" fill="#f5f3eb"/><path d="m218 32 12 4-8 10 1-8Z" fill="#e1b692"/></svg></div><div class="route-stats"><div><b>${trip.items.length}</b><span>Places</span></div><div><b>${trip.days}</b><span>Days</span></div><div><b>${countries.size}</b><span>Countries</span></div></div><p class="route-disclaimer">A little route sketch, not a geographic map. Check travel distances and opening hours before you go.</p><p>✳ ${storageWarning?'Export to keep your trip.':'Saved on this browser, just for you.'}</p></aside></div>`;
  $('#trip-name').oninput=e=>{trip.name=e.target.value;persist();$('#summary-name').textContent=trip.name||'My next adventure';};$('#trip-start').onchange=e=>{trip.start=e.target.value;persist();renderTrip();};$('#trip-days').onchange=e=>{trip.days=Number(e.target.value);trip.items.forEach(i=>i.day=Math.min(i.day,trip.days));persist();renderTrip();};
  $('#export').onclick=exportTrip;$('#print').onclick=()=>window.print();bindPlaceActions($('#main'));bindImageErrors($('#main'));
  document.querySelectorAll('[data-day]').forEach(s=>s.onchange=()=>{trip.items.find(i=>i.id===s.dataset.day).day=Number(s.value);persist();renderTrip();});document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{trip.items.find(i=>i.id===t.dataset.note).note=t.value;persist();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const name=findPlace(b.dataset.remove).name;trip.items=trip.items.filter(i=>i.id!==b.dataset.remove);persist();renderTrip();toast(`${name} removed from your trip`);});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const index=trip.items.findIndex(i=>i.id===b.dataset.move),item=trip.items[index];const same=trip.items.map((x,i)=>({x,i})).filter(o=>o.x.day===item.day);const pos=same.findIndex(o=>o.i===index),target=same[pos+Number(b.dataset.direction)]?.i;if(target===undefined)return;[trip.items[index],trip.items[target]]=[trip.items[target],trip.items[index]];persist();renderTrip();});
}
function tripItem(item){const d=findPlace(item.id),same=trip.items.filter(i=>i.day===item.day),index=same.findIndex(i=>i.id===item.id);return `<article class="trip-item">${d.image?imageMarkup(d):'<div class="empty-icon" aria-hidden="true">↗</div>'}<div><div class="location">${esc(d.country)} · ${esc(d.category)}</div><h3><button class="title-button" data-detail="${esc(d.id)}">${esc(d.name)}</button></h3>${photoCreditMarkup(d)}<div class="trip-controls"><label class="sr-label" for="day-${esc(d.id)}">Day</label><select id="day-${esc(d.id)}" data-day="${esc(d.id)}" aria-label="Day for ${esc(d.name)}">${Array.from({length:trip.days},(_,i)=>`<option value="${i+1}"${item.day===i+1?' selected':''}>Day ${i+1}</option>`).join('')}</select><button class="icon-control" data-move="${esc(d.id)}" data-direction="-1" aria-label="Move ${esc(d.name)} earlier"${index===0?' disabled':''}>↑</button><button class="icon-control" data-move="${esc(d.id)}" data-direction="1" aria-label="Move ${esc(d.name)} later"${index===same.length-1?' disabled':''}>↓</button><button class="remove" data-remove="${esc(d.id)}" aria-label="Remove ${esc(d.name)} from trip">Remove</button></div><textarea data-note="${esc(d.id)}" aria-label="Notes for ${esc(d.name)}" maxlength="500" placeholder="A café to find. A moment to make time for…">${esc(item.note)}</textarea></div></article>`;}
function exportTrip(){const lines=[trip.name||'My next adventure','Made with TripWise',trip.start?`Starts: ${trip.start}`:'Dates: whenever you’re ready',''];for(let day=1;day<=trip.days;day++){lines.push(`DAY ${day} ${tripDate(day)}`);const items=trip.items.filter(i=>i.day===day);if(!items.length)lines.push('Room for serendipity.');for(const item of items){const d=findPlace(item.id);lines.push(`- ${d.name}, ${d.country}`,`  ${item.note||'No notes yet.'}`,`  ${d.source||`https://en.wikipedia.org/wiki/${encodeURIComponent(d.id)}`}`);}lines.push('');}lines.push('Editorial suggestions only. Verify travel distances, access, visas and opening hours.','Destination information: Wikipedia (CC BY-SA).');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='tripwise-my-trip.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your trip has been exported.');}
$('#details').addEventListener('close',()=>{activeDetail=null;document.body.classList.remove('modal-open');});$('#details').addEventListener('click',e=>{if(e.target===$('#details')){const r=$('#details').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#details').close();}});
$('#surprise').onclick=()=>{if(state.loading)return toast('Finding places. One moment…');if(!state.places.length)return toast('Load destinations first, then try a little serendipity.');openDetails(state.places[Math.floor(Math.random()*state.places.length)].id);};
window.addEventListener('hashchange',()=>{state.view=location.hash==='#trip'?'trip':'explore';if($('#details').open)$('#details').close();render();window.scrollTo({top:0,behavior:'instant'});});
render();loadPlaces();
